/* QueryID : com.demo.proworks.dashboard.selectDashboardSummary */ SELECT (SELECT COUNT(DISTINCT pug.PJT_ID) FROM PROJECT_USER_GROUP pug WHERE pug.USER_ID = #{userId}) AS totalProjects,
(SELECT COUNT(t.TASK_ID) FROM PROJECT_TASK t WHERE t.USER_ID = #{userId}) AS totalTasks,
(SELECT COUNT(ir.id) FROM issues_risks ir WHERE ir.USER_ID = #{userId}) AS totalIssues


/* QueryID : com.demo.proworks.dashboard.selectProjectStatusChart */
SELECT p.PJT_STATUS AS label,
COUNT(DISTINCT p.PJT_ID) AS value
FROM PJT
p
LEFT JOIN PROJECT_USER_GROUP pug ON p.PJT_ID = pug.PJT_ID
WHERE p.USER_ID = #{userId} OR pug.USER_ID = #{userId}
GROUP BY p.PJT_STATUS;
